import os
import openpyxl
import pypdf

def examine_pdf(path):
    print(f'=== PDF: {path} ===')
    reader = pypdf.PdfReader(path)
    for i, page in enumerate(reader.pages):
        print(f'--- Page {i+1} ---')
        print(page.extract_text()[:1000])

def examine_xlsx(path):
    print(f'=== XLSX: {path} ===')
    wb = openpyxl.load_workbook(path, data_only=True)
    for sheet in wb.sheetnames:
        print(f'Sheet: {sheet}')
        ws = wb[sheet]
        for row in list(ws.iter_rows(values_only=True))[:20]:
            print(row)

project_dir = 'final_batch4__structural_task7_roof_deck_design__blind/project'
for root, dirs, files in os.walk(project_dir):
    for f in files:
        path = os.path.join(root, f)
        print('FILE:', path)
        if f.endswith('.xlsx'):
            try:
                examine_xlsx(path)
            except Exception as e:
                print('Error reading xlsx:', e)
        elif f.endswith('.pdf'):
            try:
                examine_pdf(path)
            except Exception as e:
                print('Error reading pdf:', e)
        elif f.endswith('.txt') or f.endswith('.csv'):
            try:
                with open(path, 'r', encoding='utf-8', errors='ignore') as tf:
                    print(tf.read()[:1500])
            except Exception as e:
                print('Error reading text:', e)
