import os
import openpyxl
import pdfplumber
import docx

def read_doc(path):
    print(f'=== DOC: {path} ===')
    if path.endswith('.pdf'):
        with pdfplumber.open(path) as pdf:
            for i, page in enumerate(pdf.pages):
                print(f'--- Page {i+1} ---')
                print(page.extract_text() or '')
    elif path.endswith('.xlsx'):
        wb = openpyxl.load_workbook(path, data_only=True)
        for sheet in wb.sheetnames:
            print(f'Sheet: {sheet}')
            ws = wb[sheet]
            for row in ws.iter_rows(values_only=True):
                print(row)
    elif path.endswith('.docx'):
        doc = docx.Document(path)
        for p in doc.paragraphs:
            if p.text.strip():
                print(p.text)
        for table in doc.tables:
            for row in table.rows:
                print([cell.text.strip() for cell in row.cells])
    elif path.endswith('.txt') or path.endswith('.csv'):
        with open(path, 'r', encoding='utf-8', errors='ignore') as f:
            print(f.read())

base = 'final_batch4__structural_task7_roof_deck_design__blind'
for root, dirs, files in os.walk(os.path.join(base, 'project')):
    for f in files:
        read_doc(os.path.join(root, f))
