import ifcopenshell
import ifcopenshell.util.shape

ifc_path = 'final_batch4__structural_task7_roof_deck_design__blind/15_model/DC2-A-STR_Roof_Structure_Model_RevC.ifc'
model = ifcopenshell.open(ifc_path)

def get_coords(element):
    placement = element.ObjectPlacement
    # let's get bounding box or translation
    matrix = ifcopenshell.util.shape.get_placement(placement)
    return matrix

for proxy in model.by_type('IfcBuildingElementProxy'):
    print('Proxy:', proxy.Name, proxy.Description)
    for rel in proxy.IsDefinedBy:
        if rel.is_a('IfcRelDefinesByProperties'):
            prop_def = rel.RelatingPropertyDefinition
            if prop_def.is_a('IfcPropertySet'):
                print('  Pset:', prop_def.Name)
                for prop in prop_def.HasProperties:
                    print(f'    {prop.Name}: {getattr(prop, \"NominalValue\", None)}')

for opening in model.by_type('IfcOpeningElement'):
    print('Opening:', opening.Name, opening.Description)
    # find voiding
    for rel in model.by_type('IfcRelVoidsElement'):
        if rel.RelatingOpeningElement == opening:
            print('  Voids element:', rel.RelatingBuildingElement.Name)
